import React from "react";
import { FaLinkedin, FaGithub, FaEnvelope } from "react-icons/fa";

const Footer = () => {
  return (
    <>
      <style>{`

        .footer {
          background: linear-gradient(180deg, #0b1120, #0f172a);
          color: #cbd5e1;
          padding: 30px 8%;
          text-align: center;
          border-top: 1px solid rgba(255,255,255,0.08);
          position: relative;
        }

        /* TOP GLOW LINE */
        .footer::before {
          content: "";
          position: absolute;
          top: 0;
          left: 50%;
          transform: translateX(-50%);
          width: 120px;
          height: 2px;
          background: #38BDF8;
          box-shadow: 0 0 12px #38BDF8;
          border-radius: 2px;
        }

        /* LOGO */
        .footer-logo {
          width: 52px;
          height: 52px;
          margin: 0 auto 10px;
          border-radius: 12px;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 700;
          font-size: 18px;
          letter-spacing: 1px;
          color: white;
          background: linear-gradient(135deg, #38BDF8, #2563eb);
          box-shadow: 0 0 15px rgba(56,189,248,0.4);
        }

        .footer-name {
          font-size: 1.2rem;
          font-weight: 600;
          color: #ffffff;
          margin-bottom: 6px;
        }

        .footer-tagline {
          font-size: 0.85rem;
          margin-bottom: 18px;
          color: #94a3b8;
          max-width: 420px;
          margin-left: auto;
          margin-right: auto;
        }

        .footer-icons {
          display: flex;
          justify-content: center;
          gap: 18px;
          margin-bottom: 18px;
        }

        .footer-icons a {
          width: 38px;
          height: 38px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 50%;
          background: rgba(255,255,255,0.05);
          color: #cbd5e1;
          font-size: 1rem;
          transition: all 0.3s ease;
          border: 1px solid rgba(56,189,248,0.2);
        }

        .footer-icons a:hover {
          background: #38BDF8;
          color: #ffffff;
          transform: translateY(-4px) scale(1.05);
          box-shadow: 0 0 15px rgba(56,189,248,0.6);
        }

        .footer-copy {
          font-size: 0.75rem;
          color: #64748b;
          margin-top: 10px;
        }

        /* RESPONSIVE */
        @media (max-width: 768px) {
          .footer {
            padding: 25px 6%;
          }

          .footer-logo {
            width: 46px;
            height: 46px;
            font-size: 16px;
          }

          .footer-name {
            font-size: 1.1rem;
          }
        }

      `}</style>

      <footer className="footer">

        {/* SA LOGO */}
        <div className="footer-logo">SA</div>

        <div className="footer-name">Swetha</div>

        <div className="footer-tagline">
          Transforming ideas into scalable and impactful digital solutions.
        </div>

        <div className="footer-icons">

          <a href="mailto:swethaa1805@email.com" title="Send Email">
            <FaEnvelope />
          </a>

          <a
            href="https://www.linkedin.com/in/swetha-a-0b1712382/"
            target="_blank"
            rel="noopener noreferrer"
            title="LinkedIn"
          >
            <FaLinkedin />
          </a>

          <a
            href="https://github.com/Swethaa1805"
            target="_blank"
            rel="noopener noreferrer"
            title="GitHub"
          >
            <FaGithub />
          </a>

        </div>

        <div className="footer-copy">
          © {new Date().getFullYear()} Swetha. All Rights Reserved.
        </div>

      </footer>
    </>
  );
};

export default Footer;
